import itertools
import json

def solve_puzzle():
    houses = [1, 2, 3]

    names_list = ["Arnold", "Peter", "Eric"]
    occupations_list = ["doctor", "teacher", "engineer"]
    educations_list = ["associate", "high school", "bachelor"]
    smoothies_list = ["desert", "cherry", "watermelon"]
    hobbies_list = ["gardening", "cooking", "photography"]

    def pos(arr, value):
        return arr.index(value)

    solution = None

    for names in itertools.permutations(names_list):
        # 2. Arnold is not in the third house.
        if names[2] == "Arnold":
            continue
        # From 4 and 5: Cooking is in second house and Cooking person is Peter -> Peter in second house.
        if names[1] != "Peter":
            continue

        for occupations in itertools.permutations(occupations_list):
            # From 4 and 8: Cooking is in the second house and Cooking person is a doctor -> doctor in second house.
            if occupations[1] != "doctor":
                continue

            for hobbies in itertools.permutations(hobbies_list):
                # 4. The person who loves cooking is in the second house.
                if hobbies[1] != "cooking":
                    continue
                # 9. The photography enthusiast is the person who is a teacher.
                if pos(hobbies, "photography") != pos(occupations, "teacher"):
                    continue
                # 5. The person who loves cooking is Peter.
                if pos(hobbies, "cooking") != pos(names, "Peter"):
                    continue
                # 8. Cooking person is a doctor.
                if pos(hobbies, "cooking") != pos(occupations, "doctor"):
                    continue

                for smoothies in itertools.permutations(smoothies_list):
                    # 1. Desert smoothie lover is a doctor.
                    if pos(smoothies, "desert") != pos(occupations, "doctor"):
                        continue
                    # 3. Cherry to the right of Peter (Peter is at house 2 -> cherry must be house 3).
                    if not (pos(smoothies, "cherry") > pos(names, "Peter")):
                        continue

                    for educations in itertools.permutations(educations_list):
                        # 6. Associate's degree is to the right of gardening.
                        if not (pos(educations, "associate") > pos(hobbies, "gardening")):
                            continue
                        # 7. Bachelor's degree is to the right of Desert smoothie lover.
                        if not (pos(educations, "bachelor") > pos(smoothies, "desert")):
                            continue

                        # All constraints satisfied
                        solution = {
                            "header": ["House", "Name", "Occupation", "Education", "Smoothie", "Hobby"],
                            "rows": []
                        }
                        for i in range(3):
                            solution["rows"].append([
                                str(i + 1),
                                names[i],
                                occupations[i],
                                educations[i],
                                smoothies[i],
                                hobbies[i]
                            ])
                        return solution

    return None

def main():
    sol = solve_puzzle()
    output = {"solution": sol} if sol else {"solution": None}
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    main()
